// le moulin tourne : ses ailes sont dessinées à part
const draw = function (id, [, , , ops, sw]) {
  const COL = { I: '#1A1A1A', W: '#FFFFFF', G: '#4FAE4F', B: '#8A5A2B', S: '#B8BEC6' };
  return function (B, cx, cy, R, rot, e, a) {
    const s = this.sp(a); if (s <= 0.001) return;
    const K = this.kit(cx, cy, R, rot * 0.3 + (sw ? Math.sin(this._now / 800 + e.ph1) * sw : 0), s);
    const c = k => k === 'M' ? this.cc.red : k === 'L' ? this.cc.line : k === 'BG' ? this.pal().bg : COL[k] || k, P = q => q.map(p => K.T(p[0], p[1]));
    const fr = this.eo((a - 420) / 500);
    for (const o of ops) switch (o[0]) {
      case 'e': B.fill(K.ell(o[1], o[2], o[3], o[4], o[5], 18), c(o[6])); break;
      case 'c': B.fill(K.ring(o[1], o[2], o[3], o[3], 16), c(o[4])); break;
      case 'r': B.fill(K.poly([[o[1], o[2]], [o[3], o[2]], [o[3], o[4]], [o[1], o[4]]]), c(o[5])); break;
      case 'p': B.fill(K.poly(o[1]), c(o[2])); break;
      case 'b': B.fill(P(o[1]), c(o[2])); break;
      case 'a': { const q = []; for (let i = 0; i <= 16; i++) { const t = Math.PI * (o[5] + (o[6] - o[5]) * i / 16); q.push(K.T(o[1] + Math.cos(t) * o[3], o[2] + Math.sin(t) * o[4])); } B.fill([q[0], ...q, q[16]], c(o[7])); break; }
      case 'l': B.stroke(P(o[1]), c(o[2]), K.lw * (o[3] || 1.5)); break;
      case 'o': { const q = K.ell(o[1], o[2], o[3], o[4], 0, 18); B.stroke(q.concat([q[0], q[1]]), c(o[5]), K.lw * (o[6] || 2)); break; }
      case 'k': if (fr > 0) this.strokeRange(B, P(o[1]), 0, fr, c(o[2]), K.lw * (o[3] || 1.3)); break;
    }
    if (id === 'moulin') for (let i = 0; i < 4; i++) { const t = this._now / 900 + e.ph1 + i * Math.PI / 2; B.stroke([K.T(0, -0.35), K.T(Math.cos(t) * 0.85, -0.35 + Math.sin(t) * 0.85)], c('L'), K.lw * 3.2); }
  };
};
